import os,json,subprocess
cmd=os.environ.get('CMD','')
cwd=os.environ.get('CWD','.') or '.'
if not cmd:
    print(json.dumps({'stdout':'','exit':'0'})); raise SystemExit
try:
    r=subprocess.run(cmd,shell=True,cwd=cwd,capture_output=True,text=True,timeout=15)
    print(json.dumps({'stdout':(r.stdout+r.stderr)[:6000],'exit':str(r.returncode)}))
except Exception as e:
    print(json.dumps({'stdout':'ERROR: '+str(e),'exit':'1'}))

import os,glob,re
root=os.environ.get('ROOT','.') or '.'
g=os.environ.get('GLOB','**/*') or '**/*'
try:
    rx=re.compile(os.environ.get('PATTERN',''))
except Exception as e:
    print('bad pattern: '+str(e)); raise SystemExit
out=[]
for f in glob.glob(os.path.join(root,g),recursive=True):
    if not os.path.isfile(f): continue
    try:
        for i,line in enumerate(open(f,errors='replace'),1):
            if rx.search(line):
                out.append(os.path.relpath(f,root)+':'+str(i)+': '+line.rstrip()[:200])
                if len(out)>=200: break
    except: pass
    if len(out)>=200: break
print('\n'.join(out) if out else 'no matches')

